import {createGame,startVisit,answerChart,setFocus,confirmFocus,finishVisit,buyUpgrade,FRAMES,UPGRADES} from './game.mjs';
import {loadProgress,saveProgress,clearProgress} from './storage.mjs';
const $=s=>document.querySelector(s);
let storage;try{storage=window.localStorage}catch{}
const loaded=loadProgress(storage);let game=createGame(loaded.progress),sessionOnly=loaded.sessionOnly;
const neighbors=[{name:'Milo',preference:'round',color:'#bb825e',skin:'#e5b58e',hair:'#624b3e',line:'The bookshop’s tiny print is getting a little too tiny.',kind:'Your book-loving neighbor'},{name:'Olive',preference:'cat-eye',color:'#8e9d7b',skin:'#ad795b',hair:'#3e3d34',line:'I’d love to see every little petal in my flower shop.',kind:'The neighborhood florist'},{name:'Theo',preference:'square',color:'#cfac70',skin:'#eac6a5',hair:'#b07f4c',line:'A new pair for sketching sunny days, please!',kind:'An artist around the corner'},{name:'Juniper',preference:'round',color:'#9d8ba0',skin:'#cf9474',hair:'#4c413b',line:'There’s a whole stack of recipes waiting for me.',kind:'Your friendly local baker'},{name:'Wren',preference:'cat-eye',color:'#8eaaa6',skin:'#e5b68b',hair:'#6c5544',line:'I think my next adventure needs a clearer view.',kind:'A curious little adventurer'}];
const nextPatient=()=>neighbors[game.completedVisits%neighbors.length];
const current=()=>game.visit.patient??nextPatient();
const frameName=id=>FRAMES.find(f=>f.id===id)?.name??'';
const glasses=(id,color='#58604a')=>`<svg viewBox="0 0 100 42" fill="none" aria-hidden="true"><g stroke="${color}" stroke-width="4" stroke-linejoin="round">${id==='round'?'<circle cx="26" cy="22" r="16"/><circle cx="74" cy="22" r="16"/>':id==='square'?'<rect x="9" y="8" width="34" height="28" rx="7"/><rect x="57" y="8" width="34" height="28" rx="7"/>':'<path d="M7 6 44 14Q46 40 24 35 10 33 7 6ZM93 6 56 14Q54 40 76 35 90 33 93 6Z"/>'}<path d="M43 20Q50 14 57 20M2 14 9 16M91 16 98 14"/></g></svg>`;
function person(p,full=false,frames=false){return `<svg viewBox="0 0 ${full?'100 170':'100 100'}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g>${full?'<ellipse cx="50" cy="162" rx="30" ry="5" fill="#687655" opacity=".12"/><path d="M33 118 31 151 44 151 48 120 54 120 57 151 70 151 66 118" fill="#687366"/><path d="M30 149h15v8H24q-3-7 6-8m27 0h14l6 8H57" fill="#554b3e"/>':''}<path d="M18 100q0-39 32-39t32 39${full?'v23H18Z':'Z'}" fill="${p.color}"/><path d="M25 79 17 116m58-37 8 37" stroke="${p.color}" stroke-width="12" stroke-linecap="round"/><path d="M43 63v9q7 8 14 0V63" fill="${p.skin}"/><ellipse cx="50" cy="40" rx="27" ry="31" fill="${p.hair}"/><ellipse cx="50" cy="44" rx="24" ry="27" fill="${p.skin}"/><path d="M24 38q-4-29 26-29 28 0 26 28-15-3-21-18-8 15-31 19" fill="${p.hair}"/><ellipse cx="40" cy="45" rx="2" ry="2.5" fill="#514a3d"/><ellipse cx="60" cy="45" rx="2" ry="2.5" fill="#514a3d"/><path d="M45 58q5 4 10 0" fill="none" stroke="#8d5e4e" stroke-width="1.7" stroke-linecap="round"/><ellipse cx="33" cy="53" rx="5" ry="2.3" fill="#d58b78" opacity=".5"/><ellipse cx="67" cy="53" rx="5" ry="2.3" fill="#d58b78" opacity=".5"/>${frames?'<g stroke="#695d47" stroke-width="1.8" fill="none"><circle cx="39" cy="45" r="9"/><circle cx="61" cy="45" r="9"/><path d="M48 44h4m-23-1-5-2m46 2 5-2"/></g>':''}<path d="M50 82v30" stroke="#ffffff" stroke-opacity=".25" stroke-width="1.5"/><circle cx="54" cy="89" r="1" fill="#fff" opacity=".5"/></g></svg>`;}
function plant(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cx="0" cy="37" rx="25" ry="5" fill="#a79e80" opacity=".13"/><path d="M-15 10h30l-4 26h-22Z" fill="#c49575"/><path d="M-17 9h34v6h-34Z" fill="#d2a586"/><path d="M0 10v-53M0-7-17-23M0-19 17-36" stroke="#728368" stroke-width="3"/><ellipse cx="-12" cy="-37" rx="9" ry="18" transform="rotate(-36 -12 -37)" fill="#91a17d"/><ellipse cx="12" cy="-43" rx="8" ry="17" transform="rotate(38 12 -43)" fill="#7d936d"/><ellipse cx="-15" cy="-16" rx="8" ry="15" transform="rotate(-55 -15 -16)" fill="#a8b293"/><ellipse cx="14" cy="-25" rx="8" ry="16" transform="rotate(52 14 -25)" fill="#8c9f77"/></g>`;}
function scene(){const active=!['idle','complete'].includes(game.visit.stage);const equipment=game.upgrades.includes('equipment');return `<svg viewBox="0 0 760 470" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Your sunny illustrated eye clinic, with ${game.upgrades.length} cozy upgrades"><defs><linearGradient id="wall" x2="0" y2="1"><stop stop-color="#f2efdf"/><stop offset="1" stop-color="#e9e8d7"/></linearGradient><linearGradient id="floor" x2="0" y2="1"><stop stop-color="#e2d4b9"/><stop offset="1" stop-color="#eddfc5"/></linearGradient><pattern id="boards" width="115" height="38" patternUnits="userSpaceOnUse" patternTransform="skewX(-28)"><path d="M0 0H115V38" fill="none" stroke="#d7c7a9" stroke-width="1"/></pattern><clipPath id="room"><rect x="22" y="20" width="716" height="418" rx="90"/></clipPath></defs><rect width="760" height="470" fill="#f2eee2"/><ellipse cx="380" cy="438" rx="288" ry="13" fill="#d7d4be" opacity=".3"/><g clip-path="url(#room)"><rect x="22" y="20" width="716" height="300" fill="url(#wall)"/><path d="M22 278 738 278 760 455H0Z" fill="url(#floor)"/><path d="M22 278 738 278 760 455H0Z" fill="url(#boards)"/><path d="M22 273H738" stroke="#dadcca" stroke-width="9"/><path d="M65 20V280m620-260v260" stroke="#e2e3d1" stroke-width="2"/><path d="M144 45v215h-39V45m485 0v215h39V45" fill="#fff9dc" opacity=".25"/><rect x="94" y="58" width="141" height="162" rx="66" fill="#cbd6bc" stroke="#d9d4b7" stroke-width="11"/><path d="M103 139h123M164 61v155" stroke="#fbf8e9" stroke-width="8"/><path d="M106 173q42-37 65-15t54-12v64H106Z" fill="#afc4a2"/><path d="M170 122q23-21 55 0v-8q-28-18-55 8" fill="#f7f7e8" opacity=".7"/><path d="M94 55q-12 68 1 175M237 55q13 68-1 175" stroke="#e8ddbb" stroke-width="17"/><rect x="90" y="216" width="150" height="9" rx="4" fill="#d4c8a7"/>
<g transform="translate(285 53)"><rect width="185" height="57" rx="9" fill="#faf9ec" stroke="#d5d8bd"/><text x="92" y="28" font-family="Georgia,serif" font-size="23" text-anchor="middle" fill="#6e805c">little eyes.</text><text x="92" y="43" font-family="Arial,sans-serif" font-size="6" letter-spacing="2.2" text-anchor="middle" fill="#9a9e7c">GOOD THINGS ARE IN SIGHT</text></g>
<g transform="translate(514 66)"><rect width="73" height="105" rx="4" fill="#c4b28c"/><rect x="5" y="5" width="63" height="95" rx="2" fill="#fffcf0"/><g fill="#64715a" font-family="Arial,sans-serif" font-weight="700" text-anchor="middle"><text x="36" y="35" font-size="25">E</text><text x="36" y="55" font-size="15" letter-spacing="5">F P</text><text x="38" y="73" font-size="10" letter-spacing="4">T O Z</text><text x="36" y="87" font-size="7" letter-spacing="3">L P E D</text></g></g>
<g transform="translate(630 73)"><circle r="24" fill="#f9f6e7" stroke="#b7b99b" stroke-width="4"/><circle r="2" fill="#84916f"/><path d="M0-15V0L11 6" fill="none" stroke="#839170" stroke-width="2" stroke-linecap="round"/></g>
<g transform="translate(73 259)"><ellipse cx="72" cy="54" rx="86" ry="13" fill="#b0a58c" opacity=".13"/><path d="M7 35v24m126-24v24" stroke="#a08c6c" stroke-width="7"/><rect x="-2" y="-27" width="144" height="73" rx="16" fill="#a7b08d"/><rect x="4" y="-20" width="132" height="49" rx="13" fill="#b8c09d"/><rect x="-10" y="9" width="23" height="41" rx="9" fill="#9ca980"/><rect x="128" y="9" width="23" height="41" rx="9" fill="#9ca980"/><rect x="16" y="17" width="109" height="28" rx="10" fill="#c1c6a5"/><path d="M68 21v20" stroke="#aab493"/><rect x="14" y="-10" width="30" height="29" rx="6" fill="#e3c8a6" transform="rotate(-12 29 4)"/><path d="m19-3 22 18m-22-8 17-11" stroke="#dbbb98" stroke-width="1"/></g>
<ellipse cx="383" cy="358" rx="148" ry="55" fill="#bec5a3"/><ellipse cx="383" cy="357" rx="135" ry="46" fill="none" stroke="#d6dcc0" stroke-width="2"/><ellipse cx="383" cy="357" rx="127" ry="42" fill="none" stroke="#b4bf99" stroke-width="1"/>
<g transform="translate(333 203)"><ellipse cx="42" cy="166" rx="50" ry="9" fill="#778068" opacity=".17"/><path d="M29 121h25v34H29Z" fill="#a5aaa0"/><ellipse cx="41" cy="158" rx="39" ry="8" fill="#b6baaa"/><rect x="10" y="0" width="65" height="86" rx="20" fill="#ba8f72"/><rect x="17" y="7" width="51" height="73" rx="16" fill="#d5ac8b"/><path d="M13 70h61l10 44q-44 15-87 0Z" fill="#c89e7f"/><rect x="-6" y="92" width="97" height="28" rx="11" fill="#d9b595"/><path d="M-10 65v38M92 65v38" stroke="#b0b4a3" stroke-width="7"/><path d="M-16 64h24m72 0h24" stroke="#b89675" stroke-width="9" stroke-linecap="round"/>${active?`<g transform="translate(0 5)">${person(current(),true).replace('<svg','<svg x="-2" y="-22" width="90" height="153"')}</g>`:''}</g>
<g transform="translate(460 204)"><path d="M-14 121h36M3 120V-25h-26" stroke="${equipment?'#869c8d':'#b1b4a1'}" stroke-width="8" stroke-linecap="round"/><path d="M-21-24v15" stroke="#a9ae9b" stroke-width="6"/><rect x="-49" y="-11" width="52" height="30" rx="9" fill="${equipment?'#6e8f7d':'#949f88'}"/><circle cx="-36" cy="5" r="7" fill="#e3e6d5"/><circle cx="-12" cy="5" r="7" fill="#e3e6d5"/><path d="M-26 4h4" stroke="#626f5c" stroke-width="2"/>${equipment?'<circle cx="3" cy="-35" r="5" fill="#d4e2a5"/>':''}</g>
<g transform="translate(566 237)"><ellipse cx="40" cy="111" rx="78" ry="11" fill="#b3a98c" opacity=".15"/><path d="M-3 9H94v94q-48 11-97 0Z" fill="#d3bf9c"/><rect x="-10" y="-2" width="112" height="17" rx="4" fill="#e6d4b4"/><path d="M5 29h82v26H5Z" fill="#eadab9"/><path d="M7 67h78v23H7Z" fill="#c5b18a"/><path d="M35 43h23" stroke="#bba67f" stroke-width="3" stroke-linecap="round"/><rect x="17" y="-50" width="57" height="45" rx="5" fill="#b9bba4"/><rect x="21" y="-46" width="49" height="36" rx="3" fill="#eef0dc"/><path d="M25-31h13l5-9 7 21 7-12h9" stroke="#9ba981" stroke-width="2" fill="none"/><path d="M35-5h22v7H35Z" fill="#b7b49a"/></g>
<g transform="translate(273 195)"><path d="M-24 80v17m48-17v17" stroke="#b9a47f" stroke-width="5"/><ellipse cy="79" rx="29" ry="11" fill="#d0ba93"/><path d="M-19 30h38v45h-38Z" fill="#e4d2ad"/><rect x="-24" y="26" width="48" height="9" rx="4" fill="#d3be98"/><path d="M-10 45h20m-20 12h20" stroke="#cbb68f" stroke-width="2"/><path d="M-9 24v-9h20v9" fill="#b6be9d"/><path d="M-4 15V6h11v9" fill="#e6e8d4"/></g>
${plant(660,205,.64)}${game.upgrades.includes('plant')?plant(247,319,1.1):plant(50,329,.72)}
${game.upgrades.includes('chair')?'<g transform="translate(540 362)"><ellipse cy="44" rx="43" ry="9" fill="#aaa083" opacity=".13"/><path d="M-27 17v24m54-24v24" stroke="#a78e72" stroke-width="5"/><rect x="-32" y="-29" width="64" height="59" rx="17" fill="#c58d86"/><rect x="-24" y="-22" width="48" height="37" rx="12" fill="#d9a69c"/><rect x="-36" y="6" width="72" height="24" rx="9" fill="#e0b7aa"/></g>':''}
<g transform="translate(596 131)"><rect width="68" height="5" rx="2" fill="#c4b591"/><rect x="8" y="-20" width="6" height="20" rx="1" fill="#cda885"/><rect x="16" y="-25" width="6" height="25" rx="1" fill="#a7b195"/><rect x="24" y="-18" width="7" height="18" rx="1" fill="#d8c8a2"/><path d="M45-5h14l-2 5H47Z" fill="#b69d81"/><path d="M52-5v-17m0 8-7-7m7 5 7-11" stroke="#9aa57c" stroke-width="2"/></g>
<g transform="translate(101 360)"><ellipse cx="0" cy="28" rx="47" ry="12" fill="#bbad8e" opacity=".12"/><path d="M-28 0v25m56-25v25" stroke="#b39b75" stroke-width="4"/><ellipse rx="44" ry="15" fill="#d6c29b"/><rect x="-17" y="-10" width="30" height="10" rx="2" fill="#b1b797" transform="rotate(-10)"/><path d="M-6-11 14-15" stroke="#f8f4df" stroke-width="2"/></g>
</g><g transform="translate(606 410)"><rect width="110" height="24" rx="12" fill="#fffdf0" opacity=".9"/><circle cx="13" cy="12" r="3" fill="#93a47b"/><text x="23" y="15" fill="#8b9479" font-family="Arial,sans-serif" font-size="8">A happy little place</text></g></svg>`;}
function renderScene(){$('#scene').innerHTML=scene();}
function stats(){$('#coins').textContent=game.coins.toLocaleString();$('#patients').textContent=game.completedVisits.toLocaleString();$('#upgrades-count').innerHTML=`${game.upgrades.length} <small>/ 3</small>`;$('#save-status').textContent=sessionOnly?'◌ Session only · saving unavailable':'✓ Progress saved on this device';}
function waiting(){$('#waiting').innerHTML=[0,1,2].map(i=>{const p=neighbors[(game.completedVisits+i)%neighbors.length];return `<div class="waiting-person"><div class="waiting-avatar">${person(p)}</div><div><strong>${p.name}</strong><small>${i===0?'Next in line':'Enjoying the quiet'}</small></div></div>`}).join('');}
function stepper(index){return `<div class="steps" aria-label="Step ${index+1} of 3">${[0,1,2].map(i=>`<span class="step ${i<=index?'done':''}"></span>`).join('')}</div>`;}
function focusPicture(){return `<svg viewBox="0 0 120 100" aria-hidden="true"><path d="M60 96V33M60 70 32 56M60 82l25-20" stroke="#80996b" stroke-width="5" stroke-linecap="round"/><ellipse cx="40" cy="63" rx="15" ry="7" fill="#9caf81" transform="rotate(35 40 63)"/><ellipse cx="77" cy="72" rx="15" ry="7" fill="#aebb8c" transform="rotate(-35 77 72)"/><g fill="#e4b179"><ellipse cx="60" cy="21" rx="10" ry="18"/><ellipse cx="60" cy="49" rx="10" ry="18"/><ellipse cx="46" cy="35" rx="18" ry="10"/><ellipse cx="74" cy="35" rx="18" ry="10"/><ellipse cx="50" cy="25" rx="10" ry="17" transform="rotate(-45 50 25)"/><ellipse cx="70" cy="45" rx="10" ry="17" transform="rotate(-45 70 45)"/><ellipse cx="50" cy="45" rx="10" ry="17" transform="rotate(45 50 45)"/><ellipse cx="70" cy="25" rx="10" ry="17" transform="rotate(45 70 25)"/></g><circle cx="60" cy="35" r="12" fill="#a18a56"/><circle cx="57" cy="32" r="2" fill="#cdb272"/></svg>`;}
function renderVisit(){const v=game.visit,p=current();let html='';if(v.stage==='idle'){html=`<div class="welcome"><div class="patient-portrait bob">${person(p)}</div><span class="status-pill">A friendly face is waiting</span><h2>A little hello goes a long way.</h2><p>${p.name} is here for a check-up.<br>Ready to help them see a little brighter?</p><div class="quote">“${p.line}”</div><button class="primary full" data-action="start">Invite ${p.name} in <span class="button-arrow">→</span></button><div class="reward-hint">✦ Earn 40–50 coins for a happy visit</div></div>`;}else if(v.stage==='chart'){html=`${stepper(0)}<div class="stage-label">EYE CHART · ${v.round+1} OF 3</div><h2>Which way is the E?</h2><p>Choose the direction of the open side.</p><div class="eye-box"><div class="chart-e"><span style="font-size:${[72,57,42][v.round]}px;transform:rotate(${({right:0,down:90,left:180,up:270})[v.directions[v.round]]}deg)">E</span></div><span class="chart-caption">A little focus, one letter at a time</span></div><div class="direction-grid">${[['up','↑'],['right','→'],['down','↓'],['left','←']].map(([d,a])=>`<button data-direction="${d}" aria-label="${d}">${a}<small>${d}</small></button>`).join('')}</div><p class="feedback" role="status">${game.feedback||'Tip: you can use your arrow keys, too.'}</p>`;}else if(v.stage==='focus'){html=`${stepper(1)}<div class="stage-label">THE FOCUS TEST</div><h2>A clearer kind of day.</h2><p>Move the slider until the flower comes into focus.</p><div class="eye-box"><div class="focus-picture" id="focus-picture">${focusPicture()}</div></div><label class="range-label" for="focus-slider">Adjust the lens</label><input type="range" id="focus-slider" min="0" max="100" value="${v.focusValue}" aria-describedby="focus-hint"><div class="range-ends"><span>Less focus</span><span>More focus</span></div><span class="focus-hint" id="focus-hint"></span><button class="primary full" data-action="focus">That looks clear <span class="button-arrow">→</span></button><p class="feedback" role="status">${game.feedback}</p>`;}else if(v.stage==='frames'){html=`${stepper(2)}<div class="stage-label">THE FINISHING TOUCH</div><h2>Find their happy pair.</h2><p>${p.name}’s favorite style: <strong>${frameName(p.preference)}</strong>. Match it for +10 coins.</p><div class="frames">${FRAMES.map(f=>`<button class="frame-option" data-frame="${f.id}">${glasses(f.id)}<span>${f.name}<small>${f.id===p.preference?'♡ Their favorite':'A lovely choice, too'}</small></span><span style="margin-left:auto">→</span></button>`).join('')}</div><p class="feedback" role="status">Every pair comes with a little extra care.</p>`;}else{html=`<div class="welcome"><div class="patient-portrait">${person(p,false,true)}</div><span class="status-pill">Another brighter day</span><h2>Looking good, ${p.name}!</h2><p>A clearer view. A happy neighbor.<br>That’s what your little clinic is all about.</p><div class="reward-amount">+${v.reward} <span style="font-size:17px">✦</span></div><div class="reward-breakdown">40 coins for a caring visit${v.matched?'<br>+10 for their favorite frames':''}${game.upgrades.includes('equipment')?'<br>+10 for upgraded equipment':''}</div><button class="primary full" data-action="next">Meet your next neighbor <span class="button-arrow">→</span></button><div class="reward-hint">Your progress has ${sessionOnly?'been kept for this session':'been saved. Lovely work!'}.</div></div>`;}$('#visit-content').innerHTML=html;if(v.stage==='focus')updateFocus();}
function updateFocus(){const v=game.visit,diff=Math.abs(v.focusValue-v.focusTarget);$('#focus-picture svg').style.filter=`blur(${Math.max(0,diff-3)/9}px)`;$('#focus-hint').textContent=diff<=8?'✧ Lovely and clear. You’ve found the focus!':diff<=18?'Almost there. Just a little adjustment.':v.focusValue<v.focusTarget?'Looking blurry. Try moving to the right.':'Looking blurry. Try moving to the left.';}
function shop(){$('#shop-wallet').textContent=`✦ ${game.coins} coins to make yourself at home`;$('#shop-items').innerHTML=UPGRADES.map(u=>{const owned=game.upgrades.includes(u.id),afford=game.coins>=u.cost;return `<div class="shop-item"><span class="shop-icon">${u.icon}</span><div><h3>${u.name}</h3><p>${u.description}</p></div><button class="${owned?'secondary':'primary'}" data-buy="${u.id}" ${owned||!afford?'disabled':''}>${owned?'✓ All yours':`✦ ${u.cost} coins`}${!owned&&!afford?`<small>Need ${u.cost-game.coins} more</small>`:''}</button></div>`}).join('');}
function render(){stats();renderScene();renderVisit();waiting();if($('#shop-dialog').open)shop();}
function persist(){if(!saveProgress(storage,game))sessionOnly=true;}
let returnFocus;
function openDialog(id){returnFocus=document.activeElement;if(id==='shop-dialog')shop();$('#'+id).showModal();}
for(const dialog of document.querySelectorAll('dialog')){dialog.addEventListener('close',()=>returnFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3500);}
$('#shop-nav').onclick=$('#decorate').onclick=()=>openDialog('shop-dialog');$('#help-nav').onclick=()=>openDialog('help-dialog');$('#reset-nav').onclick=$('#footer-reset').onclick=()=>openDialog('reset-dialog');$('#clinic-nav').onclick=()=>{$('.clinic-card').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.close){$('#'+b.dataset.close).close();return;}const v=game.visit;
if(b.dataset.action==='start'||b.dataset.action==='next'){const p=nextPatient();const dirs=['up','right','down','left'];game=startVisit(game,p,Array.from({length:3},()=>dirs[Math.floor(Math.random()*4)]),20+Math.floor(Math.random()*61));render();$('#visit-content button')?.focus();}
if(b.dataset.direction){game=answerChart(game,b.dataset.direction);renderVisit();if(game.visit.stage!==v.stage)$('#focus-slider')?.focus();else $(`[data-direction="${b.dataset.direction}"]`)?.focus();}
if(b.dataset.action==='focus'){game=confirmFocus(game);renderVisit();if(game.visit.stage==='frames')$('.frame-option')?.focus();else $('[data-action="focus"]')?.focus();}
if(b.dataset.frame){game=finishVisit(game,b.dataset.frame);persist();render();$('[data-action="next"]')?.focus();}
if(b.dataset.buy){const previous=game;game=buyUpgrade(game,b.dataset.buy);if(game!==previous){persist();stats();renderScene();shop();toast('A little cozier already. Make yourself at home!');$('#shop-dialog .close').focus();}}
if(b.id==='confirm-reset'){clearProgress(storage);game=createGame();persist();$('#reset-dialog').close();render();toast('A fresh little beginning. Welcome home.');}
});
document.addEventListener('input',e=>{if(e.target.id==='focus-slider'){game=setFocus(game,Number(e.target.value));updateFocus();}});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||game.visit.stage!=='chart'||e.altKey||e.ctrlKey||e.metaKey)return;const d={ArrowUp:'up',ArrowRight:'right',ArrowDown:'down',ArrowLeft:'left'}[e.key];if(d){e.preventDefault();game=answerChart(game,d);renderVisit();if(game.visit.stage==='focus')$('#focus-slider').focus();else $(`[data-direction="${d}"]`)?.focus();}});
render();
